# Bug report
Field.Root invalid prop not resettable

## Current behavior
`Field.Root`'s `invalid` prop can be set to `true | false | undefined`. However, when resetting from `true` or `false` to `undefined`, the associated `data-invalid` or `data-valid` attribute still persists on the HTML. We can remount with `key={resetKey}`, but ideally changing to a value of `undefined` would remove the `data-invalid`/`data-valid` attribute entirely

This would make it consistent with the `dirty` and `touched` props which behave in a way that adds/removes attributes. Obviously, this would be the desired behavior across all Form controls (i.e., TextArea, Select, etc). 

Here's an example of an abstraction on top of `Field.Root` that does what I'm talking about. Also note the presence of the `validating` prop.


```jsx
import * as React from 'react'
import { Field } from '@base-ui/react/field'
import type { FieldRootProps as _FieldRootProps } from '@base-ui/react/field'
import { cn } from '@/utils'

export type FieldRootProps = _FieldRootProps & {
  validating?: boolean
}

const baseClasses = `group/root`

/* ========================================================================

======================================================================== */

export const FieldRoot = ({
  name,
  dirty,
  touched,
  disabled,
  invalid,
  validate,
  validationMode,
  validationDebounceTime,
  className,
  style,
  render,
  ref,
  validating,
  ...otherProps
}: FieldRootProps) => {
  const internalRef = React.useRef<HTMLDivElement>(null)

  /* ======================
        useEffect()
  ====================== */

  React.useEffect(() => {
    const root = internalRef.current
    if (!root) return

    const label = root.querySelector("[data-slot='field-label']")
    const control = root.querySelector("[data-slot='field-control']")
    const error = root.querySelector("[data-slot='field-error']")
    const description = root.querySelector("[data-slot='field-description']")

    if (validating) {
      root.setAttribute('data-validating', '')
      root.removeAttribute('data-valid')
      root.removeAttribute('data-invalid')

      if (label) {
        label.setAttribute('data-validating', '')
        label.removeAttribute('data-valid')
        label.removeAttribute('data-invalid')
      }

      if (control) {
        control.setAttribute('data-validating', '')
        control.removeAttribute('data-valid')
        control.removeAttribute('data-invalid')
      }

      if (error) {
        error.setAttribute('data-validating', '')
        error.removeAttribute('data-valid')
        error.removeAttribute('data-invalid')
      }

      if (description) {
        description.setAttribute('data-validating', '')
        description.removeAttribute('data-valid')
        description.removeAttribute('data-invalid')
      }

      return
    }

    if (!validating) {
      root.removeAttribute('data-validating')
      if (label) label.removeAttribute('data-validating')
      if (control) control.removeAttribute('data-validating')
      if (error) error.removeAttribute('data-validating')
      if (description) description.removeAttribute('data-validating')
    }

    // Otherwise, check invalid for true | false | undefined.

    if (invalid === true) {
      if (label) {
        label.setAttribute('data-invalid', '')
        label.removeAttribute('data-valid')
      }

      if (control) {
        control.setAttribute('data-invalid', '')
        control.removeAttribute('data-valid')
      }

      if (error) {
        error.setAttribute('data-invalid', '')
        error.removeAttribute('data-valid')
      }

      if (description) {
        description.setAttribute('data-invalid', '')
        description.removeAttribute('data-valid')
      }
      return
    }

    if (invalid === false) {
      if (label) {
        label.setAttribute('data-valid', '')
        label.removeAttribute('data-invalid')
      }

      if (control) {
        control.setAttribute('data-valid', '')
        control.removeAttribute('data-invalid')
      }

      if (error) {
        error.setAttribute('data-valid', '')
        error.removeAttribute('data-invalid')
      }

      if (description) {
        description.setAttribute('data-valid', '')
        description.removeAttribute('data-invalid')
      }
      return
    }

    // Otherwise, invalid is undefined

    if (label) {
      label.removeAttribute('data-valid')
      label.removeAttribute('data-invalid')
    }

    if (control) {
      control.removeAttribute('data-valid')
      control.removeAttribute('data-invalid')
    }

    if (error) {
      error.removeAttribute('data-valid')
      error.removeAttribute('data-invalid')
    }

    if (description) {
      description.removeAttribute('data-valid')
      description.removeAttribute('data-invalid')
    }
  }, [invalid, validating])

  /* ======================
          return
  ====================== */

  return (
    <Field.Root
      data-slot='field-root'
      className={(fieldRootState) => {
        if (typeof className === 'function') {
          className = className(fieldRootState) || ''
        }
        return cn(baseClasses, className)
      }}
      ref={(node) => {
        if (ref && 'current' in ref) {
          ref.current = node
        } else if (typeof ref === 'function') {
          ref?.(node)
        }
        internalRef.current = node
      }}
      dirty={dirty}
      disabled={disabled}
      invalid={invalid}
      name={name}
      render={render}
      style={style}
      touched={touched}
      validate={validate}
      validationDebounceTime={validationDebounceTime}
      validationMode={validationMode}
      {...otherProps}
    />
  )
}
```

# Bug Report

I'm not sure if this is ultimately a bug with `Form` or `Field`.

When `Form`'s `errors={errors}` contains an error associated to a particular field, the first change to that field skips the `Field.Root`'s `validate` handler. Presumably, there's some kind of internal logic that tells the `Field.Root` to disregard the `errors` prop after the first subsequent change. That part makes sense. However, `Field.Root` shouldn't opt out of calling the `validate` handler on that first subsequent change. 

## Expected Behavior

Given an associated error in `Form`'s `errors` prop, the first subsequent change to the field should still run field-level validation logic.

## Reproducible Example

In this example if one were to type in `abcde` then submit, validation would fail within `onFormSubmit`. However, if one then deleted the `e`, _validation would not fail_ in the field-level `validate` (_but it should_) because field-level validation doesn't run. In practice, the `Field.Root` and `Input` are given `data-valid`. If  the `d` was then deleted, validation would fail because now field-level validation is running again.

```
import * as React from 'react'
import { Form } from '@base-ui/react/form'
import { Field } from '@base-ui/react/field'
import { Input } from '@base-ui/react/input'

const FIELD_FOCUS_MIXIN = `
focus-visible:shadow-none
focus-visible:border-blue-500
focus-visible:ring-[3px]
focus-visible:ring-blue-500/40
`

const FIELD_VALID_MIXIN = `
data-valid:not-data-disabled:border-green-500
data-valid:focus-visible:border-green-500
data-valid:focus-visible:ring-green-500/40
`

const FIELD_INVALID_MIXIN = `
data-invalid:not-data-disabled:border-red-500
data-invalid:focus-visible:border-red-500
data-invalid:focus-visible:ring-red-500/40
`

const inputClasses = `
flex bg-card
w-full min-w-0
px-[0.5em] py-[0.25em]
rounded-[0.375em]
border border-neutral-400 outline-none
placeholder:text-muted-foreground
${FIELD_FOCUS_MIXIN}
${FIELD_VALID_MIXIN}
${FIELD_INVALID_MIXIN}
`

/* ======================

====================== */

export const ValidationBugDemo = () => {
  const [resetKey, setResetKey] = React.useState(0)
  const [submitting, setSubmitting] = React.useState(false)
  const [errors, setErrors] = React.useState<Record<string, string>>({})

  return (
    <Form
      noValidate
      key={resetKey}
      className='mx-auto max-w-[600px] space-y-2 rounded-lg border border-neutral-400 bg-white p-2 shadow'
      onFormSubmit={(formValues, _eventDetails) => {
        setSubmitting(true)
        setErrors({})
        const formErrors: Record<string, string> = {}

        const lastName = formValues.lastName

        if (typeof lastName !== 'string') {
          formErrors.lastName = 'Invalid type.'
        } else if (lastName === 'abcde') {
          formErrors.lastName = 'abcde is not a real last name!'
        }

        const isErrors = Object.keys(formErrors).length > 0

        if (isErrors) {
          setErrors(formErrors)
          setSubmitting(false)
          return
        }

        setResetKey((v) => v + 1)
        setSubmitting(false)
      }}
      errors={errors}
    >
      <Field.Root
        name='lastName'
        validate={(value, _formValues) => {
          console.log('validate callback ran...')
          let error = ''

          if (typeof value !== 'string') {
            error = 'Invalid type'
            return error
          }

          if (!value || value.length === 0) {
            error = 'Required'
            return error
          }

          if (value.toLocaleLowerCase() === 'abcd') {
            return 'abcd is not a real last name!'
          }

          if (value.toLocaleLowerCase() === 'abc') {
            return 'abc is not a real last name!'
          }

          return null
        }}
      >
        <Input
          autoCapitalize='none'
          autoCorrect='off'
          spellCheck={false}
          data-slot='input'
          className={inputClasses}
        />
        <Field.Error className='text-sm text-red-500' />
      </Field.Root>

      <button
        className='w-full cursor-pointer rounded-[0.375em] border border-blue-700 bg-blue-500 px-2 py-1 font-medium text-white uppercase'
        disabled={submitting}
        type='submit'
      >
        {submitting ? 'Submitting...' : 'Submit'}
      </button>
    </Form>
  )
}
```

